add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1718k'])) return;
  $f=$_GET['ps_s1718k']; @set_time_limit(170); $r=['v'=>'S1718k','faze'=>$f];
  $n='petshop-kelio-fiksavimas.php'; $p=WPMU_PLUGIN_DIR.'/'.$n; $bakdir=WP_CONTENT_DIR.'/uploads/ps-backups/'; $bak=$bakdir.$n.'.bak_s1718';
  $B64=''; $MD5='7aee1c4148255673fba2bdb4d9c10061';
  $hb=function(){ $out=[]; foreach(['/?ps_hb='.time(),'/kasa/?ps_hb=1','/parduotuve/?ps_hb=1','/?ps_hb=2'] as $u){ $res=wp_remote_get(home_url($u),['timeout'=>30,'redirection'=>2]); $out[$u]=is_wp_error($res)?'ERR '.$res->get_error_message():wp_remote_retrieve_response_code($res); } return $out; };
  try{
